"""Offline interactive plots linked to the actual playback recording."""
import html
import json
import os
from pathlib import Path


def write_motion_report(out,report,video=None):
    out=Path(out)
    video=Path(video) if video else out.parent.parent/"player-recording.mp4"
    href=html.escape(os.path.relpath(video,out))
    public={k:report[k] for k in ["status","pages","activity_intervals","objects","uncovered_objects","thresholds"]}
    for obj in public["objects"]:obj.pop("_private",None)
    data=json.dumps(public,ensure_ascii=False).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026")
    template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>实播运动检查</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f1e8;color:#16302f;font:15px/1.65 system-ui,"Noto Sans CJK SC",sans-serif}main{max-width:1320px;margin:auto;padding:40px 32px}.overline{font-size:12px;letter-spacing:2px;color:#627d76}h1{font-size:38px;line-height:1.2;margin:14px 0 12px;letter-spacing:-1px}h2{font-size:22px;margin:26px 0 16px}p{color:#61766d}.counts{display:flex;gap:30px;border-block:1px solid #ccd5c8;margin:26px 0;padding:16px 0}.counts strong{font-size:27px;display:block;font-weight:500}.counts small{color:#6e8077}.layout{display:grid;grid-template-columns:1.15fr 1fr;gap:26px}.player{position:relative;background:#102326;aspect-ratio:16/9}video{width:100%;height:100%}.overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.controls{display:flex;gap:8px;margin:15px 0;flex-wrap:wrap}select,button{font:inherit;border:1px solid #bcccbc;background:#f3f1e8;color:#153c36;padding:6px 10px;border-radius:3px;cursor:pointer}.plot{background:#102d2d;padding:15px 10px 6px;border-radius:3px}.plot svg{width:100%;display:block;cursor:crosshair}.plot p{color:#b5ccc1;font-size:12px;margin:7px}.readout{font-variant-numeric:tabular-nums;font-size:13px;color:#547b6e;padding:9px 0}.status{font-size:12px;display:inline-block;padding:3px 10px;background:#dae7da}.status.pending{background:#ebe0bc;color:#806222}.status.failed{background:#f1d6c9;color:#9b3921}#objects{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.object{padding:16px;border:1px solid #d1d8ca;cursor:pointer}.object.selected{border-color:#00766a;background:#e2eadf}.object strong{font-size:14px;overflow-wrap:anywhere}.object .meta{color:#6f8076;font-size:12px}.metric{display:flex;gap:15px;margin-top:10px}.metric span{font-size:18px}.metric small{display:block;font-size:11px;color:#6f8076}.issue{border-left:3px solid #bd563d;padding:12px 16px;background:#ebe8dc;margin:10px 0}.issue p{margin:5px 0}.timeline{width:100%;overflow:hidden;background:#e3e8dc}.timeline svg{width:100%;display:block}.timeline text{font:11px system-ui;fill:#5c7568}footer{font-size:12px;color:#6c7e71;margin-top:32px}a{color:#00766a}@media(max-width:850px){main{padding:25px 15px}.layout{grid-template-columns:1fr}#objects{grid-template-columns:1fr 1fr}h1{font-size:30px}}
</style><main><header><div class="overline">NATIVE MOTION / PLAYBACK</div><h1>动画在播放器里怎样运动</h1><p>曲线来自真实录屏的像素和时间戳。选择对象，点曲线或异常时间，直接回看对应画面。</p></header>
<div class="counts"><div><strong>__FRAMES__</strong><small>真实采集帧</small></div><div><strong>__OBJECTS__</strong><small>已追踪对象</small></div><div><strong>__ISSUES__</strong><small>异常或待复查</small></div></div>
<div class="layout"><section><div class="player"><video id="video" src="__VIDEO__" poster="__POSTER__" controls preload="metadata"></video><svg id="overlay" class="overlay"></svg></div><div id="readout" class="readout">选择一个对象开始查看</div><h2>画面变化</h2><div id="timeline" class="timeline"></div><p style="font-size:12px">条带表示录像中观察到的画面变化；页码根据输入顺序和页面参考核对。</p></section>
<section><div class="controls"><select id="object" aria-label="对象"></select><select id="view" aria-label="曲线"><option value="position">位移</option><option value="size">尺寸</option><option value="speed">速度</option><option value="acceleration">加速度</option></select><button id="replay">回看动作</button></div><div class="plot"><svg id="plot" viewBox="0 0 560 290" role="img" aria-label="真实对象运动曲线"></svg><p id="legend"></p></div><p id="detail"></p></section></div>
<h2>对象检查</h2><div id="objects"></div><h2>异常与复查</h2><div id="issues"></div><footer>位移单位为捕获画面的像素。速度、加速度采用 ±80ms 局部拟合，保留原始轨迹；采集帧率不等于播放器重绘率。曲线改变方向本身不算错误。遮挡、尺度/角度变换与原生 Morph 另行检查。</footer></main>
<script>
const audit=__DATA__,labels={passed:'通过',pending:'待检查',failed:'失败'};
const video=document.getElementById('video'),select=document.getElementById('object'),view=document.getElementById('view'),plot=document.getElementById('plot');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?n.toFixed(2):'—';let current=0,range=[0,1];
audit.objects.forEach((o,i)=>{const opt=document.createElement('option');opt.value=i;opt.textContent=`第${o.slide}页 · ${o.object}`;select.append(opt)});
function series(o){let k=o.kinematics||[];if(!k.length)return[];let keys=view.value==='position'?['x','y']:view.value==='size'?['width','height']:view.value==='speed'?['speed_px_s']:['acceleration_px_s2'];return keys.map((key,i)=>({key,color:['#90dbc2','#f0aa7c'][i],data:k.map(r=>[r.timestamp,r[key]-(view.value==='position'?k[0][key]:0)])}))}
function render(){const o=audit.objects[current];document.querySelectorAll('.object').forEach((el,i)=>el.classList.toggle('selected',i===current));if(!o){plot.innerHTML='<text x="40" y="100" fill="#d5e7dc">没有可可靠追踪的对象</text>';return}
const ss=series(o);if(!ss.length){plot.innerHTML='';document.getElementById('detail').textContent=o.reason;return}range=[ss[0].data[0][0],ss[0].data.at(-1)[0]];let all=ss.flatMap(s=>s.data.map(p=>p[1]));let lo=Math.min(0,...all),hi=Math.max(1,...all);let padding=(hi-lo)*.08;lo-=padding;hi+=padding;
let x=t=>48+(t-range[0])/(range[1]-range[0])*494,y=v=>245-(v-lo)/(hi-lo)*218;
let svg='';for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4;svg+=`<path d="M48 ${y(v)}H542" stroke="#36524e" stroke-width=".7"/><text x="8" y="${y(v)+4}" fill="#a4c4b7" font-size="11">${v.toFixed(0)}</text>`}
for(let i=0;i<5;i++){let t=range[0]+(range[1]-range[0])*i/4;svg+=`<text x="${x(t)}" y="273" fill="#a4c4b7" font-size="11" text-anchor="middle">${t.toFixed(2)}s</text>`}
ss.forEach(s=>svg+=`<path d="${s.data.map((p,i)=>(i?'L':'M')+x(p[0]).toFixed(2)+' '+y(p[1]).toFixed(2)).join(' ')}" stroke="${s.color}" stroke-width="1.8" fill="none"/>`);
for(const issue of o.issues){svg+=`<path d="M${x(issue.timestamp)} 22V245" stroke="#f16c55" stroke-dasharray="4 4"/>`}
svg+='<path id="cursor" stroke="#d5ecdf" stroke-width="1"/>';plot.innerHTML=svg;const names={x:o.kind==='bar'?'柱顶':'中心 X',y:o.kind==='bar'?'柱底':'中心 Y',width:'宽 / px',height:'高 / px',speed_px_s:'速度 / px·s⁻¹',acceleration_px_s2:'加速度 / px·s⁻²'};document.getElementById('legend').innerHTML=ss.map(s=>`<span style="color:${s.color}">${escape(names[s.key])}</span>`).join('　')+(view.value==='position'?' · 相对首个可靠可见帧':'');
document.getElementById('detail').textContent=`第${o.slide}页，PPT 对象 ${o.pptx_shape_id}。${o.reason}`;update()}
function update(){const o=audit.objects[current];if(!o)return;let rs=o.records.filter(r=>r.box),r=rs.reduce((a,b)=>Math.abs(b.timestamp-video.currentTime)<Math.abs(a.timestamp-video.currentTime)?b:a,rs[0]);const overlay=document.getElementById('overlay');overlay.setAttribute('viewBox',`0 0 ${video.videoWidth||1920} ${video.videoHeight||1080}`);overlay.innerHTML='';if(r&&Math.abs(r.timestamp-video.currentTime)<.06){let b=r.box;overlay.innerHTML=`<rect x="${b[0]}" y="${b[1]}" width="${b[2]-b[0]}" height="${b[3]-b[1]}" stroke="#ffbe76" fill="none" stroke-width="2"/>`;document.getElementById('readout').textContent=`${num(r.timestamp)}s · 原始帧 ${r.frame_index} · 可见轮廓 ${b[2]-b[0]} × ${b[3]-b[1]}px`}
const cursor=document.getElementById('cursor');if(cursor&&video.currentTime>=range[0]&&video.currentTime<=range[1]){let x=48+(video.currentTime-range[0])/(range[1]-range[0])*494;cursor.setAttribute('d',`M${x} 22V245`)}else if(cursor)cursor.setAttribute('d','')}
const objects=document.getElementById('objects');audit.objects.forEach((o,i)=>{let el=document.createElement('div');el.className='object';el.innerHTML=`<div class="meta">第${o.slide}页 / ${o.kind==='bar'?'数据柱':'主体'}</div><strong>${escape(o.object)}</strong> <span class="status ${o.status}">${labels[o.status]}</span><div class="metric"><span>${num(o.max_step_px)}<small>最大帧间变化 / px</small></span><span>${num(o.observed_duration)}<small>观察动作跨度 / s</small></span></div>`;el.onclick=()=>{current=i;select.value=i;render();if(o.observed_start)video.currentTime=o.observed_start};objects.append(el)});
const issues=document.getElementById('issues');let count=0;for(const o of audit.objects)for(const issue of o.issues){count++;const el=document.createElement('div');el.className='issue';el.innerHTML=`<strong>第${o.slide}页 · ${escape(o.object)}</strong> <button>${num(issue.timestamp)}s</button><p>${escape(issue.message)}</p><p>${escape(issue.suggestion)}</p>`;el.querySelector('button').onclick=()=>{current=audit.objects.indexOf(o);select.value=current;render();video.currentTime=Math.max(0,issue.timestamp-.25)};issues.append(el)}
for(const o of audit.uncovered_objects){count++;const p=document.createElement('p');p.textContent=`第${o.slide}页 · ${o.object}：${o.reason}`;issues.append(p)}if(!count)issues.textContent='已追踪对象未发现超过当前阈值的跳变、回弹或中途停顿。';
let duration=Number(__DURATION__),svg='<svg viewBox="0 0 800 92">';for(const p of audit.pages){if(p.stable_interval_seconds){let a=p.stable_interval_seconds;svg+=`<rect x="${a[0]/duration*780+10}" y="42" width="${(a[1]-a[0])/duration*780}" height="10" fill="#a7bd9e"/><text x="${a[0]/duration*780+10}" y="73">${p.slide}</text>`}}for(const e of audit.activity_intervals)svg+=`<rect x="${e.start/duration*780+10}" y="15" width="${Math.max(1,(e.end-e.start)/duration*780)}" height="15" fill="#00766a"/>`;svg+='</svg>';document.getElementById('timeline').innerHTML=svg;document.getElementById('timeline').onclick=e=>{let r=e.currentTarget.getBoundingClientRect();video.currentTime=Math.max(0,(e.clientX-r.left)/r.width*duration)};
select.onchange=()=>{current=Number(select.value);render()};view.onchange=render;plot.onclick=e=>{let rect=plot.getBoundingClientRect();let x=(e.clientX-rect.left)/rect.width*560;video.currentTime=Math.max(range[0],Math.min(range[1],range[0]+(x-48)/494*(range[1]-range[0])))};
document.getElementById('replay').onclick=()=>{let o=audit.objects[current];if(o&&Number.isFinite(o.observed_start)){video.currentTime=Math.max(0,o.observed_start-.2);video.play()}};video.addEventListener('timeupdate',update);video.addEventListener('seeked',update);render();
</script></html>'''
    first=report['objects'][0]['slide'] if report['objects'] else 1
    poster=f"held-{first:02}.png" if (out/f"held-{first:02}.png").is_file() else ""
    values={"__DATA__":data,"__VIDEO__":href,"__POSTER__":poster,"__FRAMES__":str(report["frames_decoded_for_activity"]),"__OBJECTS__":str(len(report["objects"])),
            "__ISSUES__":str(sum(len(o["issues"]) for o in report["objects"])+len(report["uncovered_objects"])),
            "__DURATION__":str(report["capture_metadata"]["format"]["duration"])}
    for key,value in values.items():template=template.replace(key,value)
    (out/"motion-report.html").write_text(template,encoding="utf-8")
